from taf.transport.ssh.connection import connect

from ute_common_sshforwarder.server import ForwardServer
from ute_common_sshforwarder.handler import ForwardHandlerFactory
from ute_common_sshforwarder.exception import ServerIsAlreadyRunning


class Forwarder(object):
    """
    A class to handle the communication with destination machine and service via remote machine.

    Forwarder is transparent for new connections and is able to support any protocol where user is able
    to specify connection parameters like: IP address, port e.g. SSH, HTTP, HTTPS.

    Forwarder is not able to handle FTP traffic because of:

        * FTP in active mode creates port 20 for active connection - it is not possible to create forward channel for
          data.
        * FTP in passive mode negotiate with remote host new connection parameters. It is not possible to predict this
          information without sniffing the forwarding data.
    """

    def __init__(self, remote_pc_conn, remote_pc_login, dest_ip, dest_port):
        """
        :param dictionary   remote_pc_conn:     Dictionary with host of remote machine.
                                                If timeout is NOT provided, it will be explicitly set to 10. Otherwise
                                                use provided user timeout
        :param dictionary   remote_pc_login:    Dictionary with 'username' and 'password' of remote machine.
                                                If 'keyfile' is provided, tunnel will login using SSH key
        :param string       dest ip:            IP address of destination host.
        :param integer      dest_port:          Service port available on destination host.

        .. code-block:: python

            remote_pc_conn = {'host': '10.44.138.114'}
            remote_pc_login = {'username': 'ute', 'password': 'ute', 'keyfile': '/path/to/id_rsa'}
            ip = '192.168.255.1'
            port = 22
            f = Forwarder(remote_pc_conn, remote_pc_login, ip, port)
            bind_port = f.start()
            print(bind_port)    # Forwarding connection becomes available on localhost and bind_port
            f.stop()
        """
        self._remote_pc_conn = remote_pc_conn
        self._remote_pc_login = remote_pc_login
        self._dest_ip = dest_ip
        self._dest_port = dest_port
        self._server = None
        self._ssh = None
        self._bind_port = None
        self._handler_factory = None

    @property
    def dest_ip(self):
        """Returns IP address of destination host."""
        return self._dest_ip

    @dest_ip.setter
    def dest_ip(self, value):
        """Sets IP address of destination host."""
        self._dest_ip = value
        if self._handler_factory:
            self._handler_factory.remote_ip = value

    @property
    def dest_port(self):
        """Returns service port available on destination host."""
        return self._dest_port

    @dest_port.setter
    def dest_port(self, value):
        """Sets service port available on destination host."""
        self._dest_port = value
        if self._handler_factory:
            self._handler_factory.remote_port = value

    @property
    def bind_port(self):
        """Method returns port dedicated to establish services on local machine.

        :return:    Port to be used on local machine.
        :rtype:     integer
        """
        return self._bind_port

    def start(self):
        """Method starts forwarder and returns port dedicated to establish services on local machine.

        :return:    Port to be used on local machine.
        :rtype:     integer
        """
        if self._server or self._ssh:
            raise ServerIsAlreadyRunning("Server is running on port {}. Please stop it first.".format(self.bind_port))
        self._create_ssh_conn_to_remote_pc()
        self._start_forward_server()
        return self._bind_port

    def stop(self):
        """ Method stops forwarder."""
        self._shutdown_server()
        self._close_ssh()
        self._bind_port = None
        self._handler_factory = None

    def _create_ssh_conn_to_remote_pc(self):
        if 'timeout' not in self._remote_pc_conn.keys():
            self._remote_pc_conn['timeout'] = 10
        self._ssh = connect(
            username=self._remote_pc_login.get('username'),
            password=self._remote_pc_login.get('password'),
            key_path=self._remote_pc_login.get('keyfile', None),
            hostname=self._remote_pc_conn.get('host'),
            timeout=self._remote_pc_conn.get('timeout')
        )

    def _start_forward_server(self):
        self._handler_factory = ForwardHandlerFactory(self._dest_ip, self._dest_port, self._ssh._client.get_transport())
        self._server = ForwardServer(self._handler_factory)
        self._server.start()
        self._bind_port = self._server.port

    def _shutdown_server(self):
        if self._server:
            self._server.shutdown()
            self._server = None

    def _close_ssh(self):
        if self._ssh:
            self._ssh.disconnect()
            self._ssh = None
